441			relatedClause, relatedArgs := deleteUserInClause(len(args)+1, batch)
442			query := `DELETE FROM memo_relation WHERE memo_id IN ` + memoClause + ` OR related_memo_id IN ` + relatedClause
443			args = append(args, relatedArgs...)
444			if _, err := tx.ExecContext(ctx, query, args...); err != nil {
445				return err
446			}
447		}
448		return nil
449	}
450	
451	func deleteMemosTx(ctx context.Context, tx *sql.Tx, memoIDs []int32) error {
452		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
453			clause, args := deleteUserInClause(1, batch)
454			if _, err := tx.ExecContext(ctx, `DELETE FROM memo WHERE id IN `+clause, args...); err != nil {
455				return err
456			}
